// Seeds an isolated config dir + file token store with one login context
// pointing at a core that isn't listening, so `entire repo clone` reproduces
// the reported failure.
package main

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

func main() {
	dir := os.Args[1]
	coreURL := os.Args[2]

	if err := os.MkdirAll(dir, 0o700); err != nil {
		panic(err)
	}

	contexts := map[string]any{
		"current_context": "local",
		"contexts": []map[string]any{{
			"name":             "local",
			"core_url":         coreURL,
			"handle":           "alice",
			"keychain_service": "entire-core:" + coreURL,
		}},
	}
	b, err := json.MarshalIndent(contexts, "", "  ")
	if err != nil {
		panic(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "contexts.json"), b, 0o600); err != nil {
		panic(err)
	}

