// Same fixture as ../seed, but with a login JWT that is still locally valid:
// the CLI skips the refresh and the request itself hits the dead core.
package main

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

func main() {
	dir := os.Args[1]
	coreURL := os.Args[2]

	if err := os.MkdirAll(dir, 0o700); err != nil {
		panic(err)
	}

	contexts := map[string]any{
		"current_context": "local",
		"contexts": []map[string]any{{
			"name":             "local",
			"core_url":         coreURL,
			"handle":           "alice",
			"keychain_service": "entire-core:" + coreURL,
		}},
	}
	b, err := json.MarshalIndent(contexts, "", "  ")
	if err != nil {
		panic(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "contexts.json"), b, 0o600); err != nil {
		panic(err)
	}

	enc := func(s string) string { return base64.RawURLEncoding.EncodeToString([]byte(s)) }
	exp := time.Now().Add(time.Hour)
	jwt := enc(`{"alg":"HS256","typ":"JWT"}`) + "." +
		enc(fmt.Sprintf(`{"iss":%q,"handle":"alice","exp":%d}`, coreURL, exp.Unix())) + "." + enc("sig")

	tokens := map[string]map[string]string{
		"entire-core:" + coreURL: {"alice": fmt.Sprintf("%s|%d", jwt, exp.Unix())},
	}
	b, err = json.MarshalIndent(tokens, "", "  ")
	if err != nil {
		panic(err)
	}
	if err := os.WriteFile(filepath.Join(dir, "tokens.json"), b, 0o600); err != nil {
		panic(err)
	}
}

